func (s *DemoStateStore) ActiveNames(ctx context.Context, since time.Time) ([]string, error) {
	var names []string
	err := s.db.NewRaw(`SELECT state.name FROM platform.demo_school_states AS state
		JOIN platform.schools AS school ON school.id = state.tenant_id
		WHERE state.status = 'ready' AND school.deleted_at IS NULL AND state.last_used_at >= ?
		ORDER BY state.created_at, state.name`, since).Scan(ctx, &names)
	if err != nil {
		return nil, fmt.Errorf("list demo schools in use: %w", err)
	}
	return names, nil
}

func (s *DemoStateStore) Finish(ctx context.Context, name string, visitorAccountID, visitorParentAccountID int64) error {
	_, err := s.db.NewRaw(`UPDATE platform.demo_school_states
		SET status = 'ready', claimed_at = NULL,
			visitor_account_id = NULLIF(?, 0), visitor_parent_account_id = NULLIF(?, 0),
			visitor_account_ids = array_remove(visitor_account_ids || ARRAY[NULLIF(?, 0)], NULL),
			visitor_parent_account_ids = array_remove(visitor_parent_account_ids || ARRAY[NULLIF(?, 0)], NULL),
			visitor_school_ids = array_remove(visitor_school_ids || ARRAY[tenant_id], NULL)
		WHERE name = ?`, visitorAccountID, visitorParentAccountID, visitorAccountID, visitorParentAccountID, name).Exec(ctx)
	if err != nil {
		return fmt.Errorf("finish demo school order: %w", err)
	}
	return nil
}

func (s *DemoStateStore) Load(ctx context.Context, name string) (*DemoState, error) {
	var state DemoState
	err := s.db.NewRaw(`SELECT tenant_id, seed_state, COALESCE(visitor_account_id, 0) AS visitor_account_id,
		COALESCE(visitor_parent_account_id, 0) AS visitor_parent_account_id
		FROM platform.demo_school_states WHERE name = ? AND seed_state IS NOT NULL`, name).Scan(ctx, &state)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("load demo school state: %w", err)
	}
	return &state, nil
}

func (s *DemoStateStore) ReadyNames(ctx context.Context) ([]string, error) {
	var names []string
	err := s.db.NewRaw(`SELECT state.name FROM platform.demo_school_states AS state
		JOIN platform.schools AS school ON school.id = state.tenant_id
		WHERE state.status = 'ready' AND school.deleted_at IS NULL ORDER BY state.created_at, state.name`).Scan(ctx, &names)
	if err != nil {
		return nil, fmt.Errorf("list demo schools: %w", err)
	}
	return names, nil
}

func (s *DemoStateStore) ReleaseClaims(ctx context.Context) error {
	_, err := s.db.NewRaw(`UPDATE platform.demo_school_states SET claimed_at = NULL WHERE status = 'preparing' AND claimed_at IS NOT NULL`).Exec(ctx)
	if err != nil {
		return fmt.Errorf("release demo school orders: %w", err)
	}
	return nil
}

func (s *DemoStateStore) RetireMany(ctx context.Context, names []string) (hidden, erased int, err error) {
	var result struct {
		Hidden int `bun:"hidden"`
		Erased int `bun:"erased"`
	}
	if err := s.db.NewRaw(`SELECT hidden, erased FROM platform.retire_expired_demo_schools(?::text[])`, pgdialect.Array(names)).Scan(ctx, &result); err != nil {
		return 0, 0, fmt.Errorf("retire demo schools: %w", err)
	}
	return result.Hidden, result.Erased, nil
}

func (s *DemoStateStore) Return(ctx context.Context, name string) error {
	_, err := s.db.NewRaw(`UPDATE platform.demo_school_states SET claimed_at = NULL, attempts = GREATEST(attempts - 1, 0)
		WHERE name = ? AND status = 'preparing'`, name).Exec(ctx)
	if err != nil {
		return fmt.Errorf("return demo school order: %w", err)
	}
	return nil
}

