	}
	return s.findSchool(ctx, "find_school_by_slug", func(txCtx context.Context) (organizationtenancy.School, bool, domain.OperationStats, error) {
		return s.store.FindSchoolBySlug(txCtx, slug)
	})
}

func (s *Service) FindSchoolBySubdomain(ctx context.Context, subdomain string) (result organizationtenancy.School, err error) {
	subdomain = strings.TrimSpace(strings.ToLower(subdomain))
	if err := organizationtenancy.ValidateSubdomain(subdomain); err != nil {
		return organizationtenancy.School{}, err
	}
	return s.findSchool(ctx, "find_school_by_subdomain", func(txCtx context.Context) (organizationtenancy.School, bool, domain.OperationStats, error) {
		return s.store.FindSchoolBySubdomain(txCtx, subdomain)
	})
}

func (s *Service) ListOrganizations(ctx context.Context) (result []organizationtenancy.Organization, err error) {
	err = s.run(ctx, "list_organizations", func(txCtx context.Context, stats *domain.OperationStats) error {
		var queryStats domain.OperationStats
		result, queryStats, err = s.store.List(txCtx)
		stats.Add(queryStats)
		return err
	})
	if result == nil {
		result = []organizationtenancy.Organization{}
	}
	return result, err
}

func (m *TraegerMasterData) LogoImage(ctx context.Context, organizationID int64) (organizationtenancy.TraegerLogoImage, error) {
	if organizationID <= 0 {
		return organizationtenancy.TraegerLogoImage{}, errTraegerRequired
	}
	logo, found, err := m.store.LogoImage(ctx, organizationID)
	if err != nil {
		return organizationtenancy.TraegerLogoImage{}, err
	}
	if !found {
		return organizationtenancy.TraegerLogoImage{}, organizationtenancy.ErrTraegerLogoNotFound
	}
	return logo, nil
}
